#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { parseArgs } = require('node:util');
const { HARNESS_ROOT } = require('./lib/harness-root.cjs');
const { resolveState, DEFAULT_STATE_DIRNAME, STATE_LINK_FILE, STATE_MARKER } = require('./lib/harness-state.cjs');
const { envOf } = require('./io/env.cjs');

function readOptional(file) {
  try { return fs.readFileSync(file, 'utf8'); }
  catch (error) { if (error.code !== 'ENOENT') throw error; return null; }
}

function install({ check, home = os.homedir(), codexHome = envOf().codexHome || path.join(home, '.codex') }) {
  const pkg = path.join(HARNESS_ROOT, 'dist', 'plugin');
  const source = path.join(pkg, 'agents', 'codex');
  const names = fs.readdirSync(source).filter((name) => name.endsWith('.toml')).sort();
  if (!names.length) throw new Error('Build dist/plugin before installing the Codex profiles');
  const updates = new Map();
  for (const name of names) {
    const target = path.join(codexHome, 'agents', name);
    const current = readOptional(target);
    const wanted = fs.readFileSync(path.join(source, name), 'utf8');
    if (current === wanted) continue;
    if (current !== null && !current.startsWith('# Generated by logical-paradox from ')) {
      throw new Error('Codex agent profile already belongs to another installation: ' + target);
    }
    updates.set(target, wanted);
  }

  const defaultState = path.join(home, DEFAULT_STATE_DIRNAME);
  // The installed plugin cache excludes third-party binaries. Remember a runtime supplied in the checkout.
  const { findIn, profileName } = require('../mcp/matlab-server.cjs');
  const matlab = findIn([path.join(HARNESS_ROOT, 'packs/fpga/tools')]);
  if (matlab) {
    const file = path.join(defaultState, profileName);
    const wanted = JSON.stringify({ executable: matlab }, null, 2) + '\n';
    if (readOptional(file) !== wanted) updates.set(file, wanted);
  }
  const selected = resolveState({ homeDir: home, harnessRoot: HARNESS_ROOT });
  const link = path.join(defaultState, STATE_LINK_FILE);
  if (selected.stateRoot !== path.resolve(defaultState)) {
    if (fs.existsSync(path.join(defaultState, STATE_MARKER))) {
      throw new Error('The explicit state root conflicts with the already migrated state');
    }
    const current = readOptional(link);
    const wanted = JSON.stringify({ stateRoot: selected.stateRoot }, null, 2) + '\n';
    if (current !== null && path.resolve(JSON.parse(current).stateRoot) !== selected.stateRoot) {
      throw new Error('A different Harness state link already exists: ' + link);
    }
    if (current === null) updates.set(link, wanted);
  }

  if (check && updates.size) throw new Error('Codex plugin profile drift: ' + [...updates.keys()].join(', '));
  for (const [file, content] of updates) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const stage = file + '.' + process.pid + '.tmp';
    fs.writeFileSync(stage, content, { flag: 'wx' });
    fs.renameSync(stage, file);
  }
  return { profiles: names.length, stateRoot: selected.stateRoot, changed: updates.size };
}

if (require.main === module) {
  try {
    const { values } = parseArgs({ options: { check: { type: 'boolean' } } });
    console.log(JSON.stringify(install(values)));
  } catch (error) {
    console.error('[install-codex-plugin-profile] ' + error.message);
    process.exitCode = 1;
  }
}
